<!doctype html><html lang="es-PE"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Tarea <?= (int) $task['id'] ?> | Soporte CSI</title><link rel="stylesheet" href="/assets/app.css"></head><body class="min-h-screen bg-paper text-ink"><a href="#contenido" class="sr-only focus:not-sr-only focus:fixed focus:left-4 focus:top-4 focus:bg-white focus:p-3">Saltar al contenido</a><header class="bg-ink text-white"><div class="mx-auto max-w-4xl px-5 py-4"><a href="/dashboard" class="text-sm font-bold">CSI · GRED</a></div></header><main id="contenido" class="mx-auto max-w-4xl px-5 py-10"><a href="/intern/tasks" class="text-sm font-semibold text-institutional-700 underline">← Mis tareas</a><p class="mt-8 text-sm font-bold uppercase tracking-wider text-institutional-700">Tarea #<?= (int) $task['id'] ?> · <?= $e($task['public_code']) ?></p><h1 class="mt-2 break-words text-3xl font-extrabold"><?= $e($task['title']) ?></h1><p class="mt-3 text-sm font-semibold">Estado: <?= $e($stateNames[$task['state']] ?? $task['state']) ?> · Responsable: <?= $e($task['responsible_name']) ?></p><?php if (isset($_GET['saved'])): ?><p role="status" class="mt-5 rounded-lg bg-institutional-50 p-4 font-semibold">Trabajo enviado para validación.</p><?php endif; ?>
