<?php if ($task['state'] === 'assigned'): ?><section class="mt-5 rounded-2xl border border-slate-200 bg-white p-6 shadow-card"><h2 class="text-lg font-bold">Documentar trabajo</h2><p class="mt-2 text-sm text-slate-600">Describe lo realizado. El responsable validará esta intervención.</p><?php if ($formErrors !== []): ?><p role="alert" class="mt-3 rounded-lg bg-rose-50 p-3 text-sm text-rose-900"><?= $e(implode(' ', $formErrors)) ?></p><?php endif; ?><form method="post" action="/intern/tasks/<?= (int) $task['id'] ?>/submit" class="mt-4"><input type="hidden" name="_csrf" value="<?= $e($session->csrfToken()) ?>"><label for="work_note" class="block font-semibold">Trabajo realizado</label><textarea id="work_note" name="work_note" required minlength="5" maxlength="5000" rows="5" class="mt-2 w-full rounded-lg border border-slate-300 p-3 focus-visible:ring-2 focus-visible:ring-institutional-700"><?= $e($workNote) ?></textarea><button class="mt-4 min-h-11 rounded-lg bg-institutional-700 px-5 font-bold text-white hover:bg-institutional-800">Enviar para validación</button></form></section><?php elseif ($task['work_note'] !== null): ?><section class="mt-5 rounded-2xl border border-institutional-100 bg-institutional-50 p-6"><h2 class="font-bold">Trabajo documentado</h2><p class="mt-3 whitespace-pre-wrap break-words"><?= $e($task['work_note']) ?></p></section><?php endif; ?></main></body></html>
